function makeOscillation(g,s,d,o){platform(g,7.2,4.1);const rails=[],mount=new THREE.Group();g.add(mount);for(const z of [-.25,.25]){const rail=cylinder(g,.065,.065,6.1,C.metal,0,.32,z);rail.rotation.z=Math.PI/2;rails.push(rail);}box(mount,.20,1.18,1.05,0xd6e2f0,0,.69,0);for(const y of [.36,.93])for(const z of [-.38,.38])sphere(mount,.035,C.dark,.14,y,z);const mass=labCart(g,C.blue);mass.userData.drag='oscillator-amplitude';mass.name='motion-cart';const spring=flexibleTube(g,161,.025,0xa9b6c6);line(g,[V(0,.13,-1),V(0,.13,1)],C.green,true);const velocity=arrow(g,V(0,.95,0),V(1,0,0),C.orange,1),accel=arrow(g,V(0,1.25,0),V(-1,0,0),C.purple,1);label(g,'Con lắc lò xo',V(0,2.2,0),o)?.scale.set(1.9,.32,1);return(s,d,c={})=>{const amplitude=Math.abs(s.a)*.12,anchor=Math.min(-2.56,-amplitude-.9),left=Math.min(-3.05,anchor-.4),right=Math.max(3.05,amplitude+.6),x=d.x*.12;for(const rail of rails){rail.position.x=(left+right)/2;rail.scale.y=(right-left)/6.1;}mount.position.x=anchor-.16;g.userData.motionBounds=new THREE.Box3(V(left-1.4,-.05,-.6),V(right+1.4,1.8,.6));mass.position.x=x;const end=x-.44;spring.userData.update(Array.from({length:161},(_,j)=>{const f=j/160,a=f*Math.PI*22;return V(anchor+f*(end-anchor),.62+Math.cos(a)*.13,Math.sin(a)*.13);}));for(const [a,value]of [[velocity,d.v],[accel,d.acc]]){a.visible=c.switches?.vectors!==false&&Math.abs(value)>.001;a.position.set(x,a===velocity?1.0:1.4,0);a.setDirection(V(Math.sign(value)||1,0,0));a.setLength(Math.max(.03,Math.min(1.35,Math.abs(value)*.022)),.14,.07);}};}
