function makeCapacitor(g,s,d,o){platform(g,6.5,4);const p1=box(g,.06,1.4,1.1,C.orange,1.0,1,0),p2=box(g,.06,1.4,1.1,C.blue,1.5,1,0);box(g,.95,.4,.6,C.dark,-2,.35,0);label(g,'Nguồn DC',V(-2,1.0,0),o);const r=cylinder(g,.12,.12,.8,0xc3a883,-.6,.5,-1.4);r.rotation.z=Math.PI/2;const charging=new THREE.Group(),discharging=new THREE.Group();g.add(charging,discharging);tube(charging,[V(-2,.5,0),V(-2,.5,-1.4),V(-1.5,.5,-1.4)],C.cyan);tube(charging,[V(-1.5,.5,1.3),V(-2,.5,1.3),V(-2,.5,0)],0x5e89b0);tube(discharging,[V(-1.5,.5,1.3),V(-1.5,.5,-1.4)],C.green);tube(g,[V(-1.5,.5,-1.4),V(-1,.5,-1.4)],C.cyan);tube(g,[V(-.2,.5,-1.4),V(1,.5,-1.4),V(1,1,0)],C.cyan);tube(g,[V(1.5,1,0),V(2.3,.5,1.3),V(-1.5,.5,1.3)],0x5e89b0);const fieldGroup=new THREE.Group(),charges=new THREE.Group();g.add(fieldGroup,charges);for(const y of [.55,1,1.45])for(const z of [-.33,0,.33])arrow(fieldGroup,V(1.08,y,z),V(1,0,0),C.purple,.34);for(let j=0;j<6;j++){const yy=.5+j%3*.45,zz=j<3?-.35:.35;sphere(charges,.05,C.orange,.94,yy,zz);sphere(charges,.05,C.blue,1.56,yy,zz)}const indic=sphere(g,.11,C.green,-.7,.5,1.3);const l=label(g,'',V(1.2,2.15,0),o),mode=label(g,'',V(-.8,1.6,-.5),o);return(s,d,c)=>{const v=d.uc/s.u;p1.material.emissive.setHex(C.orange);p2.material.emissive.setHex(C.blue);p1.material.emissiveIntensity=p2.material.emissiveIntensity=v*.6;fieldGroup.visible=charges.visible=v>.01;charges.children.forEach(m=>m.scale.setScalar(Math.cbrt(v)));charging.visible=c.capMode!=='discharge';discharging.visible=!charging.visible;indic.material.emissiveIntensity=Math.abs(d.i)/(s.u/(s.r*1000));text(l,`Uc = ${fmt(d.uc)} V · W = ${fmt(d.energy*1000)} mJ`);text(mode,c.capMode==='discharge'?'Phóng · tách nguồn':'Nạp điện');};}
function makeBoyle(g,s,d,o){platform(g,7,4);const glass=mat(0x72b9da,{transparent:true,opacity:.075,side:THREE.DoubleSide,depthWrite:false,metalness:0});const body=mesh(g,new THREE.CylinderGeometry(.88,.88,5,40,1,true),glass,0,1.12,0);body.rotation.z=Math.PI/2;const fixed=cylinder(g,.9,.9,.12,C.metal,-2.5,1.12,0);fixed.rotation.z=Math.PI/2;const piston=cylinder(g,.85,.85,.12,C.metal,0,1.12,0);piston.userData.drag='gas-volume';piston.rotation.z=Math.PI/2;for(let j=0;j<=10;j++){const xx=-2.5+j*.5;line(g,[V(xx,2.02,-.14),V(xx,2.02,.14)],0x65849f);if(j%2===0)label(g,String(j),V(xx,2.15,0),o)?.scale.set(.33,.15,1);}const rod=cylinder(g,.075,.075,1.4,0x687f96,0,1.12,0);rod.rotation.z=Math.PI/2;for(const x of [-2,2]){box(g,.2,.7,1.7,C.dark,x,.38,0);const rim=mesh(g,new THREE.TorusGeometry(.89,.028,8,48),mat(C.blue),x,1.12,0);rim.rotation.y=Math.PI/2;}const particles=new THREE.InstancedMesh(new THREE.SphereGeometry(.045,10,8),mat(C.cyan,{emissive:C.cyan,emissiveIntensity:.25}),55);g.add(particles);const gauge=cylinder(g,.45,.45,.14,0x304c65,2.65,1.5,1.2);gauge.rotation.x=Math.PI/2;const face=cylinder(g,.39,.39,.145,0x101c2a,2.65,1.5,1.22);face.rotation.x=Math.PI/2;const needle=line(g,[V(0,0,0),V(.28,0,0)],C.orange);needle.position.set(2.65,1.5,1.31);tube(g,[V(-2.45,1.8,0),V(-2.7,2.1,.8),V(2.65,2.1,1.2),V(2.65,1.9,1.2)],0x506984,.02);const l=label(g,'',V(2.65,2.4,1.2),o);label(g,'T = 300 K · đẳng nhiệt',V(-.4,2.6,-.2),o);const dummy=new THREE.Object3D();return(s,d)=>{const width=s.v*.5,px=-2.5+width;piston.position.x=px;rod.position.x=px+.7;needle.rotation.z=Math.PI*.85-d.p/350*Math.PI*1.5;for(let j=0;j<55;j++){const radial=Math.sqrt(((j*.618)%1))*.77,angle=j*2.399+(s.t||0)*(.8+(j%5)*.1);dummy.position.set(-2.44+fold(j*.317+(s.t||0)*(.18+(j%7)*.025))*(width-.12),1.12+radial*Math.cos(angle),radial*Math.sin(angle));dummy.updateMatrix();particles.setMatrixAt(j,dummy.matrix)}particles.instanceMatrix.needsUpdate=true;text(l,`${fmt(d.p,1)} kPa · ${fmt(s.v,1)} L`);};}
function makeGas(g,s,d,o){platform(g,6.4,4);const shape=new THREE.BoxGeometry(1,1,1),glass=mesh(g,shape,mat(0x5ebbd8,{transparent:true,opacity:.04,side:THREE.DoubleSide,depthWrite:false}),0,1.35,0);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(shape),new THREE.LineBasicMaterial({color:0x5798af,transparent:true,opacity:.7}));edges.position.copy(glass.position);g.add(edges);const count=240,particles=new THREE.InstancedMesh(new THREE.SphereGeometry(.043,10,8),mat(C.cyan,{emissive:C.cyan,emissiveIntensity:.24}),count);g.add(particles);const therm=box(g,.11,2.5,.11,0x2d4960,2.8,1.4,0),fill=box(g,.08,1,.08,C.orange,2.8,1.4,.08);sphere(g,.16,C.orange,2.8,.12,.08);const l=label(g,'',V(0,3.0,0),o);const temp=label(g,'',V(2.8,2.9,0),o);const dummy=new THREE.Object3D();return(s,d)=>{const width=s.v*.5;glass.scale.set(width,2.5,2);edges.scale.copy(glass.scale);particles.count=Math.min(count,Math.round(s.n/.24*95));const speed=Math.sqrt(s.tK/300)*.55;for(let j=0;j<particles.count;j++){dummy.position.set((fold(j*.618+s.t*speed*(.25+j%7*.035))-.5)*(width-.15),.17+fold(j*.414+s.t*speed*(.28+j%5*.035))*2.34,(fold(j*.732+s.t*speed*(.22+j%11*.025))-.5)*1.85);dummy.updateMatrix();particles.setMatrixAt(j,dummy.matrix)}particles.instanceMatrix.needsUpdate=true;fill.scale.y=s.tK/600*2.5;fill.position.y=.12+fill.scale.y/2;particles.material.color.setHSL(.52-(s.tK-150)/450*.08,.80,.64);text(l,`${fmt(d.p,1)} kPa · V = ${fmt(s.v,1)} L`);text(temp,`${s.tK} K`);};}
